style.css:
@-moz-document domain("open.spotify.com") {
:root {
    --main-bg-color: #342e42;
    --semi-clear: rgba(52, 46, 66, 0.6);
    --border-radius: 12px;
    --blur-amount: 15px;
  }

  body,
  .Root__main-view,
  .Root__top-container,
  .main-view-container,
  .main-nowPlayingBar,
  .main-navBar,
  .Root__nav-bar {
    background-color: var(--semi-clear) !important;
    backdrop-filter: blur(var(--blur-amount)) !important;
    -webkit-backdrop-filter: blur(var(--blur-amount)) !important;
    border-radius: var(--border-radius);
  }

  .main-view-container__scroll-node-child,
  .main-view-container,
  .main-nowPlayingBar-nowPlayingBar {
    background-color: transparent !important;
  }

  .main-rootlist-rootlistItemLink,
  .main-rootlist-rootlistItemLink:hover {
    background-color: transparent !important;
  }

  .main-navBar-navBarLink,
  .main-navBar-navBarLinkActive {
    color: #ffffff !important;
    background-color: transparent !important;
  }

  /* optional: hide annoying stuff */
  .Root__right-sidebar,
  .Root__top-bar__right {
    display: none !important;
  }

  /* cute fonts if u want ? */
  * {
    font-family: "Poppins", "Segoe UI", sans-serif !important;
  }
}
